import{c as o,$ as i,Q as l,j as c,g as t,n as r,o as a,m as n}from"./chunks/framework.CWBTDBPu.js";const f=JSON.parse('{"title":"YuRelic 安装部署","description":"","frontmatter":{"title":"YuRelic 安装部署"},"headers":[],"relativePath":"plugins/items/yu-relic/install.md","filePath":"plugins/items/yu-relic/install.md"}'),h={name:"plugins/items/yu-relic/install.md"},p={class:"quick-actions"};function u(k,e,y,g,b,m){const d=i("CopyMarkdownButton"),s=i("CopyLLMButton");return l(),c("div",null,[e[0]||(e[0]=t("h1",{id:"yurelic-安装部署",tabindex:"-1"},[r("YuRelic 安装部署 "),t("a",{class:"header-anchor",href:"#yurelic-安装部署","aria-label":'Permalink to "YuRelic 安装部署"'},"​")],-1)),t("div",p,[a(d,{page:""}),a(s,{page:""})]),e[1]||(e[1]=n(`<h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境项</th><th>要求</th></tr></thead><tbody><tr><td>服务端</td><td>Bukkit/Spigot/Paper/Paper衍生/Youer/Arclight/其余混合端等 <code>1.8.x - 1.26.x</code>，已测试 <code>1.21.1</code></td></tr><tr><td>Java</td><td><code>JDK 8</code> 及以上；发布包保持 Java 8 字节码兼容</td></tr><tr><td>主插件目录</td><td><code>plugins/YuRelic/</code></td></tr><tr><td>配置入口</td><td><code>plugins/YuRelic/config.yml</code></td></tr><tr><td>动态依赖目录</td><td><code>plugins/YuRelic/libs/</code></td></tr><tr><td>单服存储</td><td>默认 SQLite，文件在 <code>plugins/YuRelic/data/yurelic.db</code></td></tr><tr><td>跨服存储</td><td>建议 MySQL，并为每个子服设置不同 <code>storage.server-id</code></td></tr></tbody></table><p>可选联动：<code>LevelledMobs</code>、<code>MythicMobs</code>、<code>WorldGuard</code>、<code>WorldEdit</code>、<code>Vault</code>、<code>PlayerPoints</code>、<code>EasyBot</code>、<code>PlaceholderAPI</code>。这些都是软依赖，未安装时插件应静默降级。</p><h2 id="版本来源" tabindex="-1">版本来源 <a class="header-anchor" href="#版本来源" aria-label="Permalink to &quot;版本来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>用途</th><th>获取方式</th></tr></thead><tbody><tr><td>免费版 <code>1.0.0</code></td><td>适合先测试开光、基础成长与常规服务器兼容性</td><td><a href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noreferrer">Yu 插件交流群</a></td></tr><tr><td>赞助版 <code>1.0.13.31</code></td><td>适合正式服使用完整玩法、GUI、诊断、掉落、跨服与防复制能力</td><td><a href="https://www.afdian.com/item/0699c320541211f1b9e952540025c377" target="_blank" rel="noreferrer">爱发电赞助入口</a></td></tr></tbody></table><h2 id="直接部署" tabindex="-1">直接部署 <a class="header-anchor" href="#直接部署" aria-label="Permalink to &quot;直接部署&quot;">​</a></h2><ol><li>将发布得到的 <code>YuRelic-版本-obf.jar</code> 放入服务端 <code>plugins/</code>。</li><li>第一次启动服务端，让插件生成 <code>plugins/YuRelic/</code>。</li><li>检查后台是否出现 <code>YuRelic 已启动。</code>。</li><li>执行 <code>/yurelic libs</code>，确认运行时依赖加载状态。</li><li>执行 <code>/yurelic doctor gui</code> 或 <code>/yurelic doctor summary</code>，查看配置、存储、联动和风险项。</li><li>让管理员手持可损耗装备执行 <code>/yurelic open</code>，确认开光 GUI 与物品 Lore 正常。</li></ol><h2 id="版本与发布包" tabindex="-1">版本与发布包 <a class="header-anchor" href="#版本与发布包" aria-label="Permalink to &quot;版本与发布包&quot;">​</a></h2><p>请从 Yu 插件交流群或爱发电赞助入口获取可直接部署的发布包，再按“直接部署”放入 <code>plugins/</code> 目录。</p><p>常见发布包：</p><table tabindex="0"><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><code>YuRelic-1.0.13.31-obf.jar</code></td><td>正式服建议使用的发布包，放入服务端 <code>plugins/</code> 后启动</td></tr><tr><td><code>YuRelic-1.0.0.jar</code></td><td>免费试用版发布包，适合先验证基础开光与成长流程</td></tr></tbody></table><h2 id="动态依赖" tabindex="-1">动态依赖 <a class="header-anchor" href="#动态依赖" aria-label="Permalink to &quot;动态依赖&quot;">​</a></h2><p>YuRelic 将数据库驱动、NBT-API、HikariCP、SLF4J 等运行库放到运行时加载，避免多个插件各自打包同一依赖导致类冲突。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">library</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  verify-checksum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  fail-on-required-missing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  connect-timeout-ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  read-timeout-ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60000</span></span></code></pre></div><p>首次启动会优先检查 <code>plugins/YuRelic/libs/</code>。如果服务器不能访问外网，可以手动把依赖 jar 放入该目录，再保持 <code>library.enabled: true</code>。生产服建议保持 <code>verify-checksum: true</code>。</p><h2 id="首次上线清单" tabindex="-1">首次上线清单 <a class="header-anchor" href="#首次上线清单" aria-label="Permalink to &quot;首次上线清单&quot;">​</a></h2><ul><li>给普通玩家分配基础权限：<code>yurelic.use</code>、<code>yurelic.open</code>、<code>yurelic.repair</code>、<code>yurelic.breakthrough</code>、<code>yurelic.pact</code>。</li><li>给管理员分配运维权限：<code>yurelic.reload</code>、<code>yurelic.debug</code>、<code>yurelic.libs</code>、<code>yurelic.storage</code>、<code>yurelic.diagnose</code>。</li><li>如果使用 Vault 或 PlayerPoints 支付开光、注魂、静修、商店等成本，先确认经济插件已启用。</li><li>如果使用跨服天榜、防复制和软锁，将 <code>storage.type</code> 改为 <code>MYSQL</code>，并给每个服务器不同 <code>storage.server-id</code>。</li><li>如果是混合端或模组服，先用 <code>/yurelic debugid</code> 采集特殊物品 key，再补 <code>custom-item-rules</code> 或无耐久白名单。</li><li>如果运行在较新的实验服务端版本，先在测试服确认开光、伤害、掉落、GUI 与数据库写入，再迁移到正式服。</li></ul><h2 id="升级建议" tabindex="-1">升级建议 <a class="header-anchor" href="#升级建议" aria-label="Permalink to &quot;升级建议&quot;">​</a></h2><p>YuRelic 会用 <code>config-version</code> 与 <code>messages-version</code> 管理配置迁移。升级前建议备份整个 <code>plugins/YuRelic/</code>，升级后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurelic doctor full</span></span>
<span class="line"><span>/yurelic storage status</span></span>
<span class="line"><span>/yurelic hooks</span></span></code></pre></div><p>如果诊断报告提示配置缺失或版本落后，先查看 <code>plugins/YuRelic/backups/</code> 中自动备份，再决定是接受自动补全，还是手动合并自定义配置。</p>`,21))])}const _=o(h,[["render",u]]);export{f as __pageData,_ as default};
